84:     async isValidSlpTxid(txid: string) {
85:         if(txid && !this.cachedValidations[txid]) {
86:             this.cachedValidations[txid] = { hex: null, validity: null, parents: [], details: null, invalidReason: null }
87:             this.cachedValidations[txid].hex = await this.getRawTransaction(txid);
88:         }
89: 
90:         // Check to see how we should proceed based on the validation-cache state
91:         if(!this.cachedValidations[txid].hex)
92:             await this.waitForTransactionPreProcessing(txid);
93:         if(typeof this.cachedValidations[txid].validity === 'boolean')
94:             return this.cachedValidations[txid].validity;
95:         if(this.cachedValidations[txid].details)
96:             await this.waitForParentValidationProcessing(txid);
97: 
98:         // Check SLP message validity
99:         let txn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[txid].hex)
100:         let slpmsg: SlpTransactionDetails;
101:         try {
102:             slpmsg = this.cachedValidations[txid].details = this.slp.parseSlpOutputScript(txn.outputs[0]._scriptBuffer)
103:         } catch(e) {
104:             this.cachedValidations[txid].invalidReason = "SLP OP_RETURN parsing error (" + e.message + ")."
105:             return this.cachedValidations[txid].validity = false;
106:         }
107: 
108:         // Check DAG validity
109:         if(slpmsg.transactionType === SlpTransactionType.GENESIS) {
110:             return this.cachedValidations[txid].validity = true;
111:         } 
112:         else if (slpmsg.transactionType === SlpTransactionType.MINT) {
113:             for(let i = 0; i < txn.inputs.length; i++) {
114:                 let input_txid = txn.inputs[i].prevTxId.toString('hex')
115:                 let input_txhex = await this.getRawTransaction(input_txid)
116:                 if (input_txhex) {
117:                     let input_tx: BitcoreTransaction = new bitcore.Transaction(input_txhex);
118:                     try {
119:                         let input_slpmsg = this.slp.parseSlpOutputScript(input_tx.outputs[0]._scriptBuffer)
120:                         if(input_slpmsg.transactionType === SlpTransactionType.GENESIS)
121:                             input_slpmsg.tokenIdHex = input_txid;
122:                         if(input_slpmsg.tokenIdHex === slpmsg.tokenIdHex) {
123:                             if(input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
124:                                 if(txn.inputs[i].outputIndex === input_slpmsg.batonVout)
125:                                     this.cachedValidations[txid].parents.push({ txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType ,valid: null, inputQty: null })
126:                             }
127:                         }
128:                     } catch(_) {}
129:                 }
130:             }
131:             if(this.cachedValidations[txid].parents.length !== 1) {
132:                 this.cachedValidations[txid].invalidReason = "MINT transaction must have 1 valid baton parent."
133:                 return this.cachedValidations[txid].validity = false;
134:             }
135:         }
136:         else if(slpmsg.transactionType === SlpTransactionType.SEND) {
137:             let tokenOutQty = slpmsg.sendOutputs.reduce((t,v)=>{ return t.plus(v) }, new BigNumber(0))
138:             let tokenInQty = new BigNumber(0);
139:             for(let i = 0; i < txn.inputs.length; i++) {
140:                 let input_txid = txn.inputs[i].prevTxId.toString('hex')
141:                 let input_txhex = await this.getRawTransaction(input_txid)
142:                 if (input_txhex) {
143:                     let input_tx: BitcoreTransaction = new bitcore.Transaction(input_txhex);
144:                     try {
145:                         let input_slpmsg = this.slp.parseSlpOutputScript(input_tx.outputs[0]._scriptBuffer)
146:                         if(input_slpmsg.transactionType === SlpTransactionType.GENESIS)
147:                             input_slpmsg.tokenIdHex = input_txid;
148:                         if(input_slpmsg.tokenIdHex === slpmsg.tokenIdHex) {
149:                             if(input_slpmsg.transactionType === SlpTransactionType.SEND) {
150:                                 tokenInQty = tokenInQty.plus(input_slpmsg.sendOutputs[txn.inputs[i].outputIndex])
151:                                 this.cachedValidations[txid].parents.push({txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType, valid: null, inputQty: input_slpmsg.sendOutputs[txn.inputs[i].outputIndex] })
152:                             }
153:                             else if(input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
154:                                 if(txn.inputs[i].outputIndex === 1)
155:                                     tokenInQty = tokenInQty.plus(input_slpmsg.genesisOrMintQuantity)
156:                                     this.cachedValidations[txid].parents.push({txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType, valid: null, inputQty: input_slpmsg.genesisOrMintQuantity })
157:                             }
158:                         }
159:                     } catch(_) {}
160:                 }
161:             }
162:             
163:             // Check token inputs are greater than token outputs (includes valid and invalid inputs)
164:             if(tokenOutQty.isGreaterThan(tokenInQty)) {
165:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than possible token inputs."
166:                 return this.cachedValidations[txid].validity = false;
167:             }
168:         }
169: 
170:         // Set validity validation-cache for parents, and handle MINT condition with no valid input
171:         for(let i = 0; i < this.cachedValidations[txid].parents.length; i++) {
172:             let valid = await this.isValidSlpTxid(this.cachedValidations[txid].parents[i].txid)
173:             this.cachedValidations[txid].parents.find(p => p.txid === this.cachedValidations[txid].parents[i].txid).valid = valid;
174:             if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.MINT && !valid) {
175:                 this.cachedValidations[txid].invalidReason = "MINT transaction with invalid baton parent."
176:                 return this.cachedValidations[txid].validity = false;
177:             }
178:         }
179: 
180:         // Check valid inputs are greater than token outputs
181:         if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
182:             let validInputQty = this.cachedValidations[txid].parents.reduce((t, v) => { return v.valid ? t.plus(v.inputQty) : t }, new BigNumber(0));
183:             let tokenOutQty = slpmsg.sendOutputs.reduce((t,v)=>{ return t.plus(v) }, new BigNumber(0))
184:             if(tokenOutQty.isGreaterThan(validInputQty)) {
185:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than valid token inputs."
186:                 return this.cachedValidations[txid].validity = false;
187:             }
188:         }
189: 
190:         // Check versionType is not different from any valid parent
191:         if(this.cachedValidations[txid].parents.filter(p => p.valid).length > 0) {
192:             let validVersionType = this.cachedValidations[txid].parents.find(p => p.valid).versionType;
193:             if(this.cachedValidations[txid].details.versionType !== validVersionType) {
194:                 this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid parent."
195:                 return this.cachedValidations[txid].validity = false;
196:             }
197:         } 
198:         // For case with 0 token SEND with no valid parents, must check GENESIS validity / versionType.
199:         else if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
200:             let slpmsg = this.cachedValidations[txid].details
201:             let valid = await this.isValidSlpTxid(slpmsg.tokenIdHex);
202:             if(valid) {
203:                 let genesisTxn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[slpmsg.tokenIdHex].hex)
204:                 let genesisMsg = this.slp.parseSlpOutputScript(genesisTxn.outputs[0]._scriptBuffer)
205:                 if(genesisMsg.versionType !== slpmsg.versionType) {
206:                     this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid GENESIS."
207:                     return this.cachedValidations[txid].validity = false;
208:                 }
209:             } else {
210:                 this.cachedValidations[txid].invalidReason = "SEND has 0 outputs, but has invalid token GENESIS."
211:                 console.log(this.cachedValidations[slpmsg.tokenIdHex].invalidReason)
212:                 return this.cachedValidations[txid].validity = false;
213:             }
214:         }
215: 
216:         return this.cachedValidations[txid].validity = true;
